#!/usr/bin/env python3
"""Independent after-whole-workflow Point-only original-equation oracle."""
import argparse, hashlib, json, math
from fractions import Fraction as F
from pathlib import Path

def need(ok,message):
    if not ok:raise ValueError(message)
def near(a,b,t=1e-6):need(isinstance(a,(int,float)) and not isinstance(a,bool) and math.isfinite(a) and abs(a-b)<=t,f'{a!r} != {b!r}')
def one(rows,label):need(len(rows)==1,f'one {label}, got {len(rows)}');return rows[0]
def original(snapshot,binding,distance,raw,present=True):
    s=json.loads(snapshot['capture']['native']['source']);need(s['version']==3 and len(s['objects'])==3 and len(s['stages'])==1,'actual Point-only source');need([[o['id'],o['type'],o['role'],o['stage']] for o in s['objects']]==binding['objects'],'stable actual source membership');need(all(o['type']=='Point' for o in s['objects']),'no collapsed Segment/Circle masquerading as singular Point distance');need(s['metadata']['boundaryFrame']==binding['frame']=={'origin':[0,0,0],'x':[1,0,0],'y':[0,1,0],'z':[0,0,1]},'current source frame')
    objects={o['id']:o for o in s['objects']};need(len(objects)==3 and objects[binding['unrelatedObject']]['data']=={'x':77,'y':99},'unrelated free Point stays bit-exact');a,b=[objects[binding[k]]['data'] for k in ('aObject','bObject')];need(binding['ids'][0]!=binding['ids'][1] and binding['aObject']!=binding['bObject'],'distinct actual Point identities')
    need(all(math.isfinite(p[k]) for p in (a,b) for k in ('x','y')),'finite actual coordinates');cs=s['stages'][0]['constraints'];need(len(cs)==(1 if present else 0) and s['stages'][0]['generators']==[],'only real requested DistancePP row')
    if present:
        c=cs[0];need(c['typeId']=='DistancePP' and c['objects']==binding['ids'] and c['stage']==0 and c['admission']['version']==1 and c['admission']['state'] in ('accepted','redundant'),'actual original equation identity/admission');need(str(c['constants']['distance'])==str(raw),'authored literal/name unchanged');near(math.hypot(b['x']-a['x'],b['y']-a['y']),distance)
    need(snapshot['capture']['native']['history'][0]['type']=='PLANE' and len(snapshot['capture']['native']['history'])==1,'same source graph, no fake native solid');need(snapshot['capture']['solids']['bodies']==[],'source-only report cannot claim a BRep result');owner=snapshot['ownership'];need(not owner['processing'] and not owner['resources']['cleanupFailed'] and all(owner['resources'][k]==0 for k in ('candidates','accepted','mounts')),'settled native/model resources')
    return s,a,b

def report(row,binding):
    need(row['before']==row['after'],'read-only report preserves every captured field');s,a,b=original(row['before'],binding,row['distance'],row['raw']);r=row['result'];d=r['localJacobian'];dx=F(b['x'])-F(a['x']);dy=F(b['y'])-F(a['y']);gradient=[-2*dx,-2*dy,2*dx,2*dy,F(0),F(0)];rank=int(any(gradient));singular=not rank
    need(row['singular']==singular,'singular flag derives from exact represented original gradient');need(r['revision']==row['targets']['revision'] and r['faceId']==binding['faceId'] and r['mode']=='saved' and r['scope']=='current-sketch-local-estimate','actual public request/reply binding');need(r['status']==d['status']==('zero-gradient' if singular else 'estimated'),'truthful regular/zero-gradient status')
    need(d['variables']==6 and d['equations']==1 and d['rankLower']==d['rankUpper']==d['rank']==rank and d['localNullity']==d['nullityLower']==d['nullityUpper']==6-rank,'local estimate agrees with independent original Cartesian gradient');need(d['thresholds']=={'low':1e-12,'high':1e-8} and d['method']=='equilibrated-pivoted-mgs2','actual unchanged numerical method');need(d['auxiliaryVariables']==d['fixedExternalVariables']==0,'no hidden stage/auxiliary variables');need(d['zeroGradientRows']==([0] if singular else []) and d['nearZeroGradientRows']==[],'actual gradient classification');need(r.get('physicalDof') is None and d.get('physicalDof') is None,'no physical/global freedom certificate')
    g=one(d['orderedContribution']['groups'],'actual authored group');need(g['authoredIndex']==0 and g['typeId']=='DistancePP' and g['status']==('unknown' if singular else 'estimated') and g['increment']==(None if singular else 1),'zero gradient never becomes known redundancy contribution');o=one(d['rowOrigins'],'original row');need(not o['internal'] and o['authoredIndex']==0 and all(o[k]==g[k] for k in ('constraintIndex','constraintId','typeId')),'exact original equation ownership');need(len(d['dependentRows'])==1-rank,'local row census')
    admission=one(r['admission'],'source admission');need(admission=={'index':0,'typeId':'DistancePP','objects':binding['ids'],'state':s['stages'][0]['constraints'][0]['admission']['state']},'admission stays distinct from local rank');e=one(r['evidence'],'original residual');need(e['typeId']=='DistancePP' and e['state']==admission['state'] and e['unit']=='millimeter' and e['tolerance']==1e-6 and e['units']==['millimeter'] and e['tolerances']==[1e-6] and len(e['residuals'])==1,'original mm residual profile');near(e['residuals'][0],0)
    # Squared original polynomial, evaluated independently. The existing radial
    # normalization gives physical mm rather than treating mm² as mm.
    delta=math.hypot(float(dx),float(dy));squared=dx*dx+dy*dy-F(row['distance'])**2;residual=float(squared)/(delta+row['distance']) if delta+row['distance'] else 0 if squared==0 else math.inf;near(residual,0)
    return {'case':row['case'],'label':row['label'],'distanceMm':row['distance'],'originalExactGradient':[str(v) for v in gradient],'localRank':rank,'localNullity':6-rank,'orderedContribution':g['status'],'physicalDof':None,'finiteZeroFixtureCoordinates':4 if singular else None}

def main():
    parser=argparse.ArgumentParser();parser.add_argument('evidence',type=Path);args=parser.parse_args();folder=args.evidence;r=json.loads((folder/'receipt.json').read_text());need(r['status']=='PASS' and r['ownedContextsClosed'] and r['sharedBrowserDisconnectedOnly'],'whole workflow and owned cleanup');need(r['sourceSeeds'] is False and r['privateAuthoring'] is False and r['fakeSuccessfulReplies'] is False,'genuine public authoring');need(r['sourcePins']==r['sourcePinsAfter'],'executing source unchanged');own=hashlib.sha256(Path(__file__).read_bytes()).hexdigest();need([v for k,v in r['sourcePins'].items() if k.endswith('/euclidean-point-distance/check.py')]==[own],'actual standalone oracle pin')
    need(set(r['bindings'])=={'ordinary','singular'},'both real source cases')
    for case,binding in r['bindings'].items():
        observed=one([x for x in r['rows'] if x['case']==case and x['label']=='Actual discovered point identities'],'real initial public discovery')['inspection'];points={p['id']:p for p in observed['points']};need(all(id in points for id in binding['ids']),'actual public point IDs');need([points[id]['parentId'] for id in binding['ids']]==[binding['aObject'],binding['bObject']],'source reference parent custody, no ID spelling assumptions')
        label='Original two points and unrelated Point' if case=='ordinary' else 'Two distinct valid coincident Points';initial=one([x for x in r['rows'] if x['case']==case and x['label']==label],'actual initial source');_,a,b=original(initial['before'],binding,0,0,False);need(a=={'x':0,'y':0} and b==({'x':3,'y':4} if case=='ordinary' else {'x':0,'y':0}),'publicly requested initial coordinates')
    reports=[report(row,r['bindings'][row['case']]) for row in r['rows'] if row.get('kind')=='diagnostic'];need(any(x['case']=='ordinary' and x['distanceMm']==20 for x in reports) and sum(x['case']=='singular' and x['distanceMm']==0 for x in reports)==4,'actual positive reedit and singular persistence reports')
    for row in r['rows']:
        if row.get('kind')=='source':original(row['before'],r['bindings'][row['case']],row['distance'],row['raw'],row['present'])
        if row.get('kind')=='refusal':
            need(row['outcome']['ok'] is False and not row['outcome']['error']['committed'] and not row['outcome']['error']['possiblyCommitted'] and row['before']==row['after'],'actual refusal preserves all captured source/history/quantity/journal/resource fields')
    seed=one([x for x in r['rows'] if x.get('kind')=='uncertain-seed'],'real singular-seed invocation');need(seed['constructivelySatisfiable'] is True and seed['infeasibilityClaim'] is False and r['uncertainSeed']['outcome']==seed['outcome'],'convergence observation is not a theorem of infeasibility')
    if not seed['outcome']['ok']:need(seed['before']==seed['after'] and not seed['outcome']['error']['committed'] and not seed['outcome']['error']['possiblyCommitted'],'failed singular-seed request preserves exact accepted free source')
    need(len(r['saved'])==4,'four actual saved sources');saved=[];expected={'distance-typed15':('ordinary',15,'gap',[{'name':'gap','dimension':'length','expression':'mm(15)'}]),'distance-typed20':('ordinary',20,'gap',[{'name':'gap','dimension':'length','expression':'mm(20)'}]),'distance-zero':('singular',0,0,[]),'distance-zero-bound':('singular',0,'zero',[{'name':'zero','dimension':'length','expression':'mm(0)'}])}
    for row in r['saved']:
        case,distance,raw,definitions=expected[row['label']];need(row['case']==case and row['distance']==distance and row['raw']==raw and row['definitions']==definitions and row['binding']==r['bindings'][case],'frozen independent save meaning');data=(folder/row['savedFile']).read_bytes();need(len(data)==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256'],'actual browser/server SHA and bytes');native=json.loads(data);need(native['format']=='codi-jsketcher-project' and native['version']==2 and native['unit']=='millimeter','real native source envelope');project=native['project'];before=row['before']['capture']['native'];need(project['model']['history']==before['history'] and project['model']['counters']==before['counters'] and project['model']['expressions']==before['expressions'],'exact authored graph/counters/parameters');need(len(project['sketches'])==1,'one actual owned sketch source');sketch=project['sketches'][0];need(sketch['id']==row['binding']['faceId'] and sketch['data']==json.loads(before['source']),'actual saved IDs/definitions/admission/coordinates');original(row['before'],row['binding'],distance,raw)
        script=project['model']['expressions'];prefix='codi-physical-parameters:1\n';need((script.startswith(prefix) and json.loads(script[len(prefix):])==definitions) if definitions else script=='','exact named length definitions and true zero');need('localJacobian' not in data.decode() and 'constraintId' not in data.decode(),'no solved diagnostics/ephemeral locator persisted');saved.append({'file':row['savedFile'],'sha256':row['sha256'],'distanceMm':distance,'binding':raw})
    runtime=[row for row in r['rows'] if row['label']=='Exact composed runtime'];need(len(runtime)==6,'two initial plus four fresh Open runtime bindings')
    for row in runtime:need({a['name']:a['sha256'] for a in row['assets']}==r['pins']['files'] and row['outer']['sha256']==r['pins']['outer']['sha256'],'exact current composed asset cohort')
    cause=seed['outcome'].get('error',{}).get('cause');nonconvergence=bool(cause and cause['kind']=='numerical-convergence-failure');print(json.dumps({'status':'PASS_SCOPED_DISTANCE_PP','reports':reports,'nativeFiles':saved,'singularSeedActualOutcome':seed['outcome'],'infeasibilityClaim':False,'genuineNonconvergenceObserved':nonconvergence,'remainingNonconvergenceCoverage':not nonconvergence,'limits':['Exact original Point-only gradient/rank does not certify general nonlinear freedom.','Finite d0 forces p=q despite a zero first-order gradient; local nullity6 is not physical DOF.','No BRep solid, arbitrary constraint family, multistage creation or external interchange claim.']},indent=2))

if __name__=='__main__':main()
